-- L29-l1-anime-bank-lot1.sql (run O1, lane animebank, owner request 2026-11-09; generated by apps/quiz/e2e/o1/L1/anime-bank-lot1-sql.mjs, do not edit by hand)
--
-- What:   files 27 of the 85 L08 anime drafts as verified, scheduled daily quizzes, one a day from 2026-11-21 to 2026-12-17 (each question re-read from its
--         cited page and fixed or replaced where needed: docs/anime/data/verify/bank-lot1.json), and moves the stuck row 'Name That Series: Deep Cuts'
--         from 2026-11-08 (never published: the anime cron had not reached otakuquiz) to 2026-12-18. Per row: questions (and title or description when fixed),
--         status 'scheduled', scheduled_date, verified_at = now(), verification_notes. Nothing else: no group, no other row, no kpop row.
--         27 of the 30 planned days are filled (the second reading carried 27 quizzes clean of duplicates; the free slots are 2026-12-19 to 2026-12-21, after the moved row).
-- Needs:  L08 (the 99 draft rows), 009 and 010 (quiz_bank_site_date, per-site daily), L04 (anime groups). The owner fills {REVIEWER} and {REVIEW_DATE} in the one review line below after his review:
--         while they are unfilled the file refuses to apply.
-- WHEN:   after a backup, outside a build, never between 23:50 and 00:30 UTC, and before the evening of 2026-11-20 (the anime daily runs out after 2026-11-20).
-- Verify: select count(*) from public.quiz_bank where site_id = 'anime' and status = 'scheduled' and scheduled_date between '2026-11-21' and '2026-12-17';   expect 27
--         select scheduled_date from public.quiz_bank where site_id = 'anime' and title = 'Name That Series: Deep Cuts';   expect 2026-12-18
--         select count(*) from public.quiz_bank where site_id = 'anime' and status = 'draft';   expect 58 (the 85 L08 drafts less the 27 filed here, if none was touched before)
-- Undo:   L29-l1-anime-bank-lot1.rollback.sql (exact L08 values back, refused once one of these rows is published).
-- o1-transaction: single (psql --single-transaction). Idempotent: a second run changes nothing. A row changed since L08 is left alone and makes the self-check fail.

set lock_timeout = '5s';
set client_min_messages = warning;

create temp table _l29_review (reviewer text, review_date text) on commit drop;
insert into _l29_review values ('{REVIEWER}', '{REVIEW_DATE}');

do $o1l$ begin
  if exists (select 1 from _l29_review where reviewer ~ '[{](REVIEWER|REVIEW_DATE)[}]' or review_date ~ '[{](REVIEWER|REVIEW_DATE)[}]') then
    raise exception 'L29: review not recorded (replace {REVIEWER} and {REVIEW_DATE} in the _l29_review line), nothing applied';
  end if;
  if not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'quiz_bank' and column_name = 'site_id') then
    raise exception 'L29: quiz_bank.site_id is missing (apply 002a first)';
  end if;
  if not exists (select 1 from pg_indexes where schemaname = 'public' and indexname = 'quiz_bank_site_date') then
    raise exception 'L29: quiz_bank_site_date is missing (apply 009 and 010 first)';
  end if;
end $o1l$;

create temp table _l29 (l08_title text, title text, description text, scheduled_date date, questions jsonb, old_questions jsonb, notes_sources text) on commit drop;

insert into _l29 values
  ('Soul Reapers, Films and Fifteen Openings', 'Soul Reapers, Films and Fifteen Openings', 'A look at how Bleach was made, from Tite Kubo''s manga to the Thousand-Year Blood War.', '2026-11-21'::date, $o1q$[{"question":"Who handed her powers to Ichigo to turn him into a Substitute Soul Reaper?","options":["Orihime Inoue","Rukia Kuchiki","Isshin Kurosaki","Kisuke Urahara"],"correct":1,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["bleach-ichigo-substitute-020"],"source_url":"https://en.wikipedia.org/wiki/Bleach_(manga)"},{"question":"Which network aired the first Bleach anime between 2004 and 2012?","options":["Nippon Television","Fuji Television","TBS","TV Tokyo"],"correct":3,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["bleach-anime-production-007"],"source_url":"https://en.wikipedia.org/wiki/Bleach_(TV_series)"},{"question":"On what date did the Bleach manga end in Weekly Shonen Jump?","options":["7 August 2001","5 October 2004","22 August 2016","27 March 2012"],"correct":2,"kind":"manga","spoiler":{"arc":0,"scope":"both"},"fact_ids":[],"source_url":"https://en.wikipedia.org/wiki/Bleach_(manga)"},{"question":"Which of the four Bleach films came out first, in December 2006?","options":["The DiamondDust Rebellion","Fade to Black","Memories of Nobody","Hell Verse"],"correct":2,"kind":"episode","spoiler":{"arc":0,"scope":"both"},"fact_ids":["bleach-four-films-019"],"source_url":"https://en.wikipedia.org/wiki/Bleach_(TV_series)"},{"question":"Which Bleach film came out in December 2008?","options":["Memories of Nobody","Fade to Black","Hell Verse","The DiamondDust Rebellion"],"correct":1,"kind":"film","spoiler":{"arc":0,"scope":"both"},"fact_ids":[],"source_url":"https://en.wikipedia.org/wiki/Bleach_(TV_series)"},{"question":"Which band sang *~Asterisk~, the first opening of the 2004 to 2012 Bleach anime?","options":["UVERworld","High and Mighty Color","Aqua Timez","Orange Range"],"correct":3,"kind":"music","spoiler":{"arc":0,"