do $o1l$ declare n int; applied int; m int; moved_done int; begin
  -- Refuse if another anime row is already scheduled in the window (a lot row already in its place and the moved row do not count).
  if exists (
    select 1 from public.quiz_bank b
    where b.site_id = 'anime' and b.scheduled_date between '2026-11-21' and '2026-12-21' and b.status in ('scheduled', 'verified', 'published')
      and not exists (select 1 from _l29 v where md5(lower(btrim(b.title))) in (md5(lower(btrim(v.title))), md5(lower(btrim(v.l08_title)))) and b.scheduled_date = v.scheduled_date)
      and not (md5(lower(btrim(b.title))) = md5('name that series: deep cuts') and b.scheduled_date = '2026-12-18')
  ) then
    raise exception 'L29: another anime row is already scheduled between 2026-11-21 and 2026-12-21, nothing applied';
  end if;

  -- The 27 lot rows, only while still in their L08 state.
  update public.quiz_bank b set
    title = v.title, description = v.description, questions = v.questions, status = 'scheduled', scheduled_date = v.scheduled_date,
    verified_at = now(), verification_notes = v.notes_sources || 'Anime daily bank lot 1 (L29). Each question re-read on 2026-11-09 against its cited page, see docs/anime/data/verify/bank-lot1.json and bank-lot1.md; owner review packet docs/anime/editorial/packets/bank-lot1.html. Drafted with AI assistance, checked by ' || r.reviewer || ' on ' || r.review_date || '.', updated_at = now()
  from _l29 v cross join _l29_review r
  where b.site_id = 'anime' and md5(lower(btrim(b.title))) = md5(lower(btrim(v.l08_title)))
    and b.status = 'draft' and b.scheduled_date is null and b.verified_at is null and b.published_quiz_id is null and b.questions = v.old_questions;
  get diagnostics n = row_count;

  -- The stuck row, only while scheduled on 2026-11-08 and unpublished.
  update public.quiz_bank b set scheduled_date = '2026-12-18', updated_at = now()
  where b.site_id = 'anime' and md5(lower(btrim(b.title))) = md5('name that series: deep cuts')
    and b.status = 'scheduled' and b.scheduled_date = '2026-11-08' and b.published_quiz_id is null;
  get diagnostics m = row_count;

  select count(*) into applied from public.quiz_bank b join _l29 v on md5(lower(btrim(b.title))) = md5(lower(btrim(v.title)))
    where b.site_id = 'anime' and b.status = 'scheduled' and b.scheduled_date = v.scheduled_date and b.questions = v.questions and b.published_quiz_id is null;
  select count(*) into moved_done from public.quiz_bank b
    where b.site_id = 'anime' and md5(lower(btrim(b.title))) = md5('name that series: deep cuts') and b.status = 'scheduled' and b.scheduled_date = '2026-12-18' and b.published_quiz_id is null;

  -- Self-check: exactly 27 lot rows changed plus the moved row (or a second run: none), and every lot row is in its final state.
  if not ((n = 27 and m in (0, 1)) or (n = 0 and m = 0)) or applied <> 27 or moved_done <> 1 then
    raise exception 'L29 self-check failed: % lot rows changed (expected 27 or 0), % in final state (expected 27), moved row changed %, moved row in place % (expected 1); a row changed since L08 or published, nothing applied', n, applied, m, moved_done;
  end if;
end $o1l$;
